<script setup lang="ts">
import {onBeforeUnmount,ref,watch} from 'vue'
import {applicationReady} from '../database/application'
import {searchContent} from './search'
import type {ContentHit,ContentMode} from './search'
const props=defineProps<{query:string;mode:ContentMode}>()
const emit=defineEmits<{(event:'open',url:string):void}>()
const entries=ref<ContentHit[]>([]);const total=ref(0);const loading=ref(false);const error=ref('');let sequence=0
async function load(append=false):Promise<void>{const request=++sequence;loading.value=true;error.value='';if(!append){entries.value=[];total.value=0}try{if(!applicationReady.value||!props.query.trim())return;const result=await searchContent(props.query,props.mode,{offset:append?entries.value.length:0});if(request!==sequence)return;entries.value=append?[...entries.value,...result.entries]:result.entries;total.value=result.total}catch(cause){if(request===sequence)error.value=cause instanceof Error?cause.message:'检索失败，请重试'}finally{if(request===sequence)loading.value=false}}
watch([()=>props.query,()=>props.mode,applicationReady],()=>{void load()},{immediate:true});onBeforeUnmount(()=>{sequence++})
function handleOpen(item:ContentHit):void{emit('open',item.isTitleMatch?`/pages/book-detail/index?id=${encodeURIComponent(item.bookId??'')}`:item.kind==='word'?`/pages/word-detail/index?word=${encodeURIComponent(item.word??'')}`:`/pages/context-detail/index?id=${encodeURIComponent(item.bookId??'')}&offset=${item.startOffset??0}&query=${encodeURIComponent(props.query.trim())}`)}
</script>
<template><scroll-view class="content-search-scroll" scroll-y :show-scrollbar="false"><div class="content-search-panel"><p class="content-search-note">{{ mode==='word'?'词语来自内置组词记录，不拼接单字释义。':'全文检索本机资料及内置 TXT；内置 PDF 阅读后纳入检索。' }}</p><p aria-live="polite">{{ loading?'正在检索…':`找到 ${total} 条结果` }}</p><p v-if="error" role="alert">{{ error }}</p><button v-if="error" role="button" class="content-search-more" @click="load()">重试检索</button><button v-for="item in entries" :key="item.id" role="button" class="content-search-hit" @click="handleOpen(item)"><strong>{{ item.word??item.bookName }}</strong><span>{{ item.snippet }}</span><small>{{ item.isTitleMatch?'查看图书详情':item.kind==='word'?'查看组词来源':'查看上下文和原文位置' }} →</small></button><p v-if="!entries.length&&!loading&&!error" class="content-search-note">{{ query.trim()?'没有匹配内容，可换个词或先导入资料。':'输入想查找的词语或原文片段。' }}</p><button v-if="entries.length<total" role="button" class="content-search-more" :disabled="loading" @click="load(true)">加载更多结果</button></div></scroll-view></template>
<style scoped>.content-search-scroll { flex:1;min-height:0;width:100%; }.content-search-panel { padding:18px 20px;color:var(--color-text);font-size:14px; }.content-search-note { font-size:12px;line-height:1.8;color:var(--color-text-secondary); }.content-search-hit { display:block;width:100%;margin:0;padding:18px 0;border:0;border-bottom:1px solid var(--color-border);border-radius:0;text-align:left;background:transparent;color:var(--color-text);line-height:1.8; }.content-search-hit::after {border:0}.content-search-hit strong,.content-search-hit span,.content-search-hit small { display:block;overflow-wrap:anywhere; }.content-search-hit span { margin:8px 0;font-size:13px;white-space:pre-wrap; }.content-search-hit small { font-size:11px;color:var(--color-primary); }.content-search-more { width:100%;min-height:44px;margin:16px 0;border:0;background:var(--color-primary-soft);color:var(--color-primary);font-size:13px; }</style>
